"""Build exactly twelve offline paginated HTML acceptance pages from outputs."""
import html
import json
from pathlib import Path

TASK=Path('docs/tasks/climateos_physics_validation_001')
def read(name):return json.loads((TASK/name).read_text(encoding='utf-8'))
def table(headers,rows):
    return '<div class="table-scroll"><table><thead><tr>'+''.join(f'<th>{html.escape(str(x))}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{html.escape(str(x))}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def figure(name,caption):return f'<figure><img src="charts/{name}.svg" alt="{html.escape(caption)}"><figcaption>{caption}</figcaption></figure>'
def sources(*items):return '<details><summary>公式、代码与原始数值</summary><ul>'+''.join(f'<li><a href="{u}">{t}</a></li>' for t,u in items)+'</ul></details>'
def main():
    p1,p2,p3,p4,c,tests,full=[read(x) for x in ['p1.json','p2.json','p3.json','p4.json','conservation.json','physics-tests.json','full-suite.json']]
    ipcc='https://www.ipcc-nggip.iges.or.jp/public/2006gl/pdf/5_Volume5/V5_3_Ch3_SWDS.pdf'
    code='../../../cczps_lite/integration/physics_validation.py'
    common=[('数值核心 Python',code),('锁定合成输入','inputs.json'),('运行输出与守恒','conservation.json')]
    pages=[]
    def slide(title,body,refs=()):pages.append((title,body+sources(*(list(refs)+common))))
    slide('受限物理计算验收',f'''<p class="eyebrow">CLIMATEOS-PHYSICS-VALIDATION-001 · V0.1</p><h2 class="cover">四项计算已运行<br>真实设施验证仍待数据</h2><p class="lead">参考公式与合成输入。固定参数、独立算术、质量守恒和中性响应均可复算。</p>{table(['模块','实际执行','证据类型'],[['P1','温压、湿度和参考条件转换','理想气体算术'],['P2','储存与单向逸散','未校准纯甲烷箱'],['P3','年度 IPCC FOD','2006公式、合成废物史'],['P4','单独温度/水分响应','嵌套假设模型']])}<p class="notice">D3 DATA_NOT_READY · P1-A PENDING · 无 ACCU、气候归因或部署</p>''',[('Founder完整授权','FOUNDER_AUTHORIZATION.md'),('授权原评论','https://github.com/simon947161/eco-agent-system/pull/137#issuecomment-6680117578')])
    dry=[r for r in p1['rows'] if r['vapour_pa']==0]
    slide('P1：同摩尔分数下的温压转换',f'''<p class="formula">c = x<sub>dry</sub>(P − e) M / (R T)　　r = x<sub>dry</sub> M / M<sub>air</sub></p><p>固定 2 ppm、293.15 K，P 为站点绝对压力。R=8.314462618 J/(mol·K)，M=0.016043 kg/mol。</p>{figure('p1-pressure','曲线由运行代码计算，展示相同干摩尔分数和不同温度。')}{table(['P (Pa)','c (mg/实际m³)','r (mg/kg dry air)'],[[r['pressure_pa'],f"{r['mass_concentration_kg_per_m3']*1e6:.6f}",f"{r['mass_mixing_ratio_kg_per_kg_dry_air']*1e6:.6f}"] for r in dry])}<p>体积浓度变化不能直接解释为排放质量变化。Mair=0.028965 kg/mol 是声明的近似。</p>''',[('NOAA 干摩尔分数','https://gml.noaa.gov/ccgg/carbontracker-ch4/glossary.html'),('P1 CSV','p1.csv')])
    wet=[r for r in p1['rows'] if r['pressure_pa']==80000]
    slide('P1：湿度与参考体积',f'''<p class="formula">x<sub>wet</sub> = x<sub>dry</sub>(P − e)/P<br>V<sub>ref,dry</sub> = V<sub>actual,wet</sub> (P − e)/P<sub>ref</sub> · T<sub>ref</sub>/T</p>{figure('p1-water','输入 e 为明确指定的水汽分压，未把相对湿度直接当成分压。')}{table(['80000 Pa下 e (Pa)','湿摩尔分数 (ppm)','1实际湿m³对应参考干m³'],[[r['vapour_pa'],f"{r['x_wet_mol_per_mol']*1e6:.4f}",f"{r['reference_dry_volume_per_actual_wet_m3']:.6f}"] for r in wet])}<p>参考条件为 101325 Pa、273.15 K、干气。已检查正逆转换、零极限和同一气体量的甲烷质量一致。</p>''',[('P1逐项结果','p1.json'),('独立测试','../../../tests/test_physics_validation.py')])
    slide('P2：合成储气箱与边界',f'''<p class="formula">P<sub>i</sub> = a m，a = RT/(MV)<br>v = C max(P<sub>i</sub> − P<sub>e</sub>, 0)，dm/dt = g − v</p><p>纯甲烷、定温定容箱。V=1 m³，T=293.15 K，g=0.001 kg/h，C=2×10⁻⁶ kg/(h·Pa)，初始压差500 Pa。参数全部合成，单向阀无进气。</p>{figure('p2-vent','三情景仅改变外压斜率：−100、0、+100 Pa/h，其余条件一致。')}<p class="notice">这不是垃圾体多孔介质或负压集气模型。短期逸散可来自原有储存，不能解释为产气立即增加。</p>''',[('P2完整时序','p2.json'),('压力机制适用边界','https://agupubs.onlinelibrary.wiley.com/doi/full/10.1002/2013GB004571')])
    rows=[[n,f"{r['input_kg']:.6f}",f"{r['vented_kg']:.6f}",f"{r['final_kg']-r['initial_kg']:.6f}",f"{r['residual_kg']:.2e}"] for n,r in p2['runs'].items()]
    slide('P2：质量守恒与步长误差',f'''<p class="formula">m<sub>0</sub> + ΣgΔt − ΣvΔt − m<sub>end</sub> = residual</p>{table(['情景','输入kg','逸散kg','库存变化kg','残差kg'],rows)}{figure('p2-convergence','显式Euler对线性斜坡解析解的终点误差。步长减半，误差随之下降。')}<p>稳定/正性约束 C·a·Δt ≤ 1。本轮 Δt=0.125 h；不稳定步长拒绝执行，不靠截零掩盖守恒误差。封闭、零生成、初始欠压均已作为对照运行。</p>''',[('步长收敛 CSV','p2-convergence.csv')])
    slide('P3：IPCC 2006 年度 FOD',f'''<p class="formula">D<sub>t</sub> = W<sub>t</sub>·DOC·DOCf·MCF<br>A<sub>t</sub> = D<sub>t</sub> + A<sub>t−1</sub>e<sup>−k</sup><br>Decomp<sub>t</sub> = A<sub>t−1</sub>(1 − e<sup>−k</sup>)</p>{figure('p3-stock','各批次库存分别跟踪，年度总库存等于所有存活cohort之和。')}<p>废物史10、12、8 Gg后归零；初始DDOC=0.5 Gg C；k=0.1 yr⁻¹。DOC=0.15、DOCf=0.5、MCF=1均为合成参数，未取默认参数表。</p><p>新增投入本年不衰减，下一年1月1日开始，代表平均六个月延迟。没有混入2019参数表。</p>''',[('IPCC 2006 Eq3.2/3.4/3.5，印刷页3.9',ipcc),('P3 cohort库存','p3.json')])
    slide('P3：甲烷分配与独立算例',f'''<p class="formula">G = Decomp · F · 16/12<br>E = (G − R<sub>recovered</sub>)(1 − OX)</p>{figure('p3-partition','合成设定 F=0.5、回收比例0.4、氧化比例0.1；氧化只作用于未回收部分。')}{table(['12年积分','运行结果'],[['生成 Gg CH4',f"{p3['total_generated_CH4_Gg']:.9f}"],['逸散 Gg CH4',f"{p3['total_emitted_CH4_Gg']:.9f}"],['末期DDOC Gg C',f"{p3['final_DDOC_Gg_C']:.9f}"]])}<p>独立手算：10 Gg投入、零初始库存、k=ln2，第二年分解0.375 Gg C，生成0.25 Gg CH4，逸散0.135 Gg CH4。1 Gg=10⁶ kg。守恒仅覆盖DDOC碳库存和甲烷分配，不是所有废物组分的质量平衡。</p>''',[('IPCC 2006 Eq3.1/3.6，印刷页3.8/3.10',ipcc),('P3逐年 CSV','p3.csv')])
    slide('P4：C0与中性响应完全重合',f'''<p>C0直接使用P3函数。C1保留相同废物史、初始库存、延迟、年度步长、回收与氧化，只替换有效衰减率 k。</p>{figure('p4-neutral','温度=Tref或水分指数=参考值时，C1−C0在全部年度均为0。')}{table(['检查','结果'],[['温度中性，完整输出比较','exact equality'],['水分中性，完整输出比较','exact equality'],['最大逸散差 Gg CH4','0'],['气体储存/回收/氧化重复计入','无，P2独立，不与P3/P4串接']])}<p>年度内k为常数，使用指数式精确积分。未进行更细时间步的场址预测，也未制造日尺度排放精度。</p>''',[('P4所有C0/C1输出','p4.json')])
    slide('P4：单独温度响应',f'''<p class="formula">k<sub>T</sub> = k<sub>0</sub> exp[−E<sub>a</sub>/R · (1/T − 1/T<sub>ref</sub>)]</p><p>Arrhenius数学族，Tref=293.15 K，Ea=30000 J/mol为合成值。输入是虚构的年度过程温度，不是Cooma气温或垃圾体实测温度。</p>{figure('p4-temperature','只有温度响应变化，水分没有同时变化。')}{table(['12年逸散积分','Gg CH4'],[['C0',f"{p3['total_emitted_CH4_Gg']:.9f}"],['温度C1',f"{p4['C1_temperature_only']['total_emitted_CH4_Gg']:.9f}"]])}<p>有限时间窗积分差异与末期库存相对应，不是证明生成潜力增加或模型更准确。</p>''',[('IUPAC Arrhenius定义','https://goldbook.iupac.org/terms/view/A00446'),('温度逐年倍率图','charts/p4-temperature-input.svg'),('温度 CSV','p4-temperature.csv')])
    slide('P4：单独水分响应',f'''<p class="formula">f(θ) = θ/θref　(θ≤θref)<br>f(θ) = 1+(θ−θref)/(1−θref)　(θ&gt;θref)<br>k<sub>θ</sub> = k<sub>0</sub> f(θ)，θref=0.5</p>{figure('p4-moisture','θ是0至1的合成归一化指数，倍率0至2，尚无经验甲烷标定。')}{table(['12年逸散积分','Gg CH4'],[['C0',f"{p3['total_emitted_CH4_Gg']:.9f}"],['水分C1',f"{p4['C1_moisture_only']['total_emitted_CH4_Gg']:.9f}"]])}<p>分段线性是自定的示例响应，数值插值有数学依据，生物物理响应尚待验证。没有降雨转土壤水分映射，没有同时加入温度响应。</p>''',[('NIST线性插值数学背景','https://dlmf.nist.gov/3.3'),('水分逐年倍率图','charts/p4-moisture-input.svg'),('水分 CSV','p4-moisture.csv')])
    values=[x['total_emitted_CH4_Gg'] for x in p4['temperature_parameter_grid']]
    slide('参数敏感性与不可辨识性',f'''{figure('p4-sensitivity','12组确定性参数组合：k=0.05/0.1/0.2 yr⁻¹，Ea=0/15/30/45 kJ/mol。')}{table(['探索范围','12年逸散结果'],[['温度参数网格极值 Gg CH4',f"{min(values):.6f} 至 {max(values):.6f}"],['水分参考值0.4/0.5/0.6 Gg CH4',' / '.join(f"{x['total_emitted_CH4_Gg']:.6f}" for x in p4['moisture_reference_sensitivity'])]])}<p>这不是概率分布或置信区间。仅凭净排放不能同时识别生成、覆盖层氧化、收集和储存；本轮没有拟合任何参数。</p><p>较快衰减可把释放提前，但长期潜力受投入库存限制。缺少独立观测时不作模型优劣排序。</p>''',[('完整参数网格','p4.json'),('既有CarbonOS比较边界','https://github.com/simon947161/eco-agent-system/blob/2ec66ae41ae2e1d4a0f1aaa92aa98c9f0ff4c5b0/docs/research/carbonos/batch-d/README.md')])
    slide('验收结果与ChatGPT科学评审',f'''{table(['验证层级','结果'],[['独立算术/实现测试',f"{tests['tests_run']}项通过，{tests['errors']}错误"],['完整仓库测试',f"{full['tests_run']}项，跳过{full['skipped']}项，错误{full['errors']}项"],['P2最大守恒残差 kg',f"{c['P2_max_absolute_residual_kg']:.3e}"],['P3 DDOC守恒残差 Gg C',f"{c['P3_absolute_carbon_residual_Gg_C']:.3e}"],['中性参数回归','精确一致'],['独立现场观测验证','NOT_PERFORMED'],['P2/P4物理假设','HYPOTHETICAL / UNCALIBRATED'],['外部CI','以新Draft PR检查状态为准，独立于本地记录']])}<p class="notice">D3 DATA_NOT_READY。P1-A科学准入PENDING。受限计算完成不代表真实设施排放已验证。</p><p>请ChatGPT审查：年度延迟、cohort库存和单位是否正确；P2单向箱与P4响应的适用边界是否足够；中性嵌套、守恒和独立oracle是否充分。任何扩大数据、物理过程或现场推断均等待Founder决定。</p>''',[('测试日志','physics-tests.log'),('完整测试记录','full-suite.json'),('来源与版本','sources.json'),('哈希清单','manifest.json'),('复算和交接','README.md')])
    assert len(pages)==12
    sections=[]
    for i,(title,body) in enumerate(pages,1):
        sections.append(f'<section id="slide-{i}" aria-labelledby="title-{i}" hidden><div class="page-label">参考/合成计算 · {i:02d} / 12</div><h1 id="title-{i}">{title}</h1>{body}</section>')
    css='''*{box-sizing:border-box}body{display:flex;flex-direction:column;margin:0;background:#edf1f3;color:#132f43;font:18px/1.55 "Microsoft YaHei","Segoe UI",sans-serif}main{width:100%;max-width:1180px;margin:auto;padding:34px 48px 110px;background:white;min-height:calc(100vh - 70px)}section[hidden]{display:none!important}.page-label,.eyebrow{font-size:14px;letter-spacing:.05em;color:#426f76}h1{font-size:32px;line-height:1.3;margin:12px 0 20px}h2.cover{font-size:48px;line-height:1.25;margin:28px 0}p{margin:12px 0}.lead{font-size:23px;max-width:880px}.formula{font-family:"Cambria Math","Microsoft YaHei",serif;font-size:23px;background:#f3f7f7;padding:16px 20px;border-left:4px solid #137e80}figure{margin:18px 0}img{display:block;width:100%;max-height:330px;object-fit:contain}figcaption{font-size:14px;color:#475e68;margin-top:5px}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:16px;margin:16px 0}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid #dce5e8}th{background:#f1f6f7}a{color:#116e8b;overflow-wrap:anywhere}.notice{padding:12px 0;color:#754a19;border-top:2px solid #c48b42;font-size:17px}details{margin:20px 0;font-size:15px}summary{cursor:pointer}nav{order:-1;position:sticky;top:0;left:0;right:0;background:#132f43;color:white;display:flex;align-items:center;justify-content:center;gap:18px;padding:12px;z-index:2}button,select{font:inherit;padding:8px 16px;border-radius:4px;border:1px solid #88a7b3;background:white;color:#132f43;min-height:44px}button:disabled{opacity:.5}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #e4a548;outline-offset:3px}@media(max-width:650px){body{font-size:16px}main{padding:22px 18px 105px}h1{font-size:26px}h2.cover{font-size:34px}.lead,.formula{font-size:19px}.formula{padding:12px}table{font-size:14px}th,td{padding:8px}img{max-height:none}nav{gap:9px;padding:10px 6px}button{padding:7px 10px}select{max-width:115px;font-size:15px}}@media print{nav{display:none}main{padding:0}section[hidden]{display:block!important}section{break-after:page}details{display:block}}'''
    js='''(()=>{const pages=[...document.querySelectorAll('section')],sel=document.querySelector('select'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),counter=document.querySelector('#counter');let current=0;function show(n,hash=true){current=Math.max(0,Math.min(pages.length-1,n));pages.forEach((p,i)=>p.hidden=i!==current);sel.value=String(current);prev.disabled=current===0;next.disabled=current===pages.length-1;counter.textContent=`${current+1} / ${pages.length}`;document.title=`${current+1}/12 · ${pages[current].querySelector('h1').textContent}`;if(hash)history.replaceState(null,'',`#slide-${current+1}`);window.scrollTo(0,0)}function fromHash(){const m=location.hash.match(/^#slide-(\\d+)$/);show(m?Number(m[1])-1:0,false)}prev.onclick=()=>show(current-1);next.onclick=()=>show(current+1);sel.onchange=()=>show(Number(sel.value));document.addEventListener('keydown',e=>{if(['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}else if(e.key==='Home'){e.preventDefault();show(0)}else if(e.key==='End'){e.preventDefault();show(11)}});window.addEventListener('hashchange',fromHash);fromHash()})();'''
    options=''.join(f'<option value="{i}">第{i+1}页</option>' for i in range(12))
    out=f'<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ClimateOS物理计算验收</title><style>{css}</style></head><body><main>'+''.join(sections)+f'</main><nav aria-label="报告翻页"><button id="prev">上一页</button><span id="counter" aria-live="polite"></span><select aria-label="选择页码">{options}</select><button id="next">下一页</button></nav><script>{js}</script></body></html>'
    (TASK/'index.html').write_text(out,encoding='utf-8')
    print('Built 12 real-output HTML pages')


if __name__=='__main__':main()
